mapper.select:
SELECT COUNT(1) > 0
FROM meal_record
WHERE member_id = #{memberId}
AND meal_record_id = #{mealRecordId}

SELECT meal_record_id
FROM meal_record
WHERE member_id = #{memberId}
  AND meal_date = #{mealDate}
  AND meal_time = #{mealTime}

mapper.update:
UPDATE meal_record
SET
    meal_date = #{mealUpdateDto.mealDate},
    meal_time = #{mealUpdateDto.mealTime},
    memo = #{mealUpdateDto.memo},
    meal_photo_url = #{mealUpdateDto.mealPhotoUrl}
WHERE meal_record_id = #{mealRecordId}
AND member_id = #{memberId}

mapper.delete:
DELETE FROM meal_record
WHERE meal_record_id = #{mealRecordId}
    AND member_id = #{memberId}
